$company_page_title='Notas de crédito da empresa';require APPPATH.'views/admin/includes/native_company_official_head.php';$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($q='')=>CompanyRequestScope::adminUrl($this,'credit_notes?source=company'.($q===''?'':'&'.ltrim($q,'?&')));
