<section data-company-workspace class="company-settings-card"><h1>Notas de crédito da empresa</h1><p>Documentos e movimentos privados da empresa ativa. Reembolsos registrados exigem comprovante de operação já realizada; esta tela não transfere dinheiro.</p>
<?php if($error){?><p role="alert" class="alert alert-danger"><?= $esc($error); ?></p><p><a href="<?= $esc($url()); ?>">Reabrir a lista</a></p><?php } ?>
<?php if($document){$id=$document['id'];?><h2><?= $esc($document['number'].' — '.$states[$document['status']]); ?></h2><p><?= $esc($document['identity']['legal_name'].' → '.$document['recipient']['name']); ?> · <?= $esc($document['date']); ?></p><p>Total <?= $esc($document['currency'].' '.$document['amounts']['total']); ?> · Aplicado <?= $esc($document['applied']); ?> · Reembolsado <?= $esc($document['refunded']); ?> · Saldo disponível <?= $esc($document['available']); ?></p><p><a href="<?= $esc($url('?credit='.$id.'&pdf=1')); ?>">Baixar PDF privado da nota de crédito</a></p>
<table class="table"><thead><tr><th>Descrição</th><th>Quantidade</th><th>Preço</th><th>Tributos</th></tr></thead><tbody><?php foreach($document['items'] as $item){?><tr><td><?= $esc($item['description']); ?></td><td><?= $esc($item['qty']); ?></td><td><?= $esc($item['rate']); ?></td><td><?php foreach($item['taxes'] as $tax){ ?><?= $esc($tax['name'].' '.$tax['rate'].'%'); ?><br><?php } ?></td></tr><?php } ?></tbody></table><p>Subtotal <?= $esc($document['amounts']['subtotal']); ?> · Tributos <?= $esc($document['amounts']['tax']); ?> · Desconto <?= $esc($document['amounts']['discount_total']); ?> · Ajuste <?= $esc($document['amounts']['adjustment']); ?></p><p><?= nl2br($esc($document['note'])); ?></p>
<h3>Histórico preservado</h3><?php if(!$document['entries']){?><p>Nenhum movimento.</p><?php }else{?><ul><?php foreach($document['entries'] as $entry){?><li><?= $esc($kinds[$entry['kind']].' · '.$entry['book_date'].' · '.$entry['amount'].' · '.$entry['reference']); ?><p><?= nl2br($esc($entry['reason'])); ?></p>
<?php if($document['status']!==3&&$capabilities['edit']&&$capabilities['payment_delete']&&in_array($entry['kind'],['apply','refund'],true)&&($entry['kind']!=='apply'||$capabilities['invoice_view'])){?>
<details><summary><?= $entry['kind']==='apply'?'Estornar aplicação':'Estornar reembolso registrado'; ?></summary><?= form_open($url());$hidden($entry['kind']==='apply'?'unapply':'refund_reverse'); ?><input type="hidden" name="credit_id" value="<?= $id; ?>"><input type="hidden" name="movement[parent_key]" value="<?= $esc($entry['request_key']); ?>"><?php if($entry['kind']==='apply'){?><input type="hidden" name="movement[invoice_id]" value="<?= (int)$entry['invoice_id']; ?>"><?php } ?><p>O writer verifica o saldo remanescente do movimento original. O registro original e os estornos anteriores são preservados.</p><?php $movementField='reverse-'.$entry['request_key'];require APPPATH.'views/admin/credit_notes/movement_fields.php'; ?><button type="submit">Registrar estorno local do movimento</button><?= form_close(); ?></details><?php } ?></li><?php } ?></ul><?php } ?>
<?php if($document['status']!==3&&$capabilities['edit']&&$capabilities['payment_create']){?>
<?php if($capabilities['invoice_view']){?><h3>Aplicar crédito em fatura</h3><?= form_open($url());$hidden('apply'); ?><input type="hidden" name="credit_id" value="<?= $id; ?>"><label for="credit-apply-invoice">Fatura da mesma empresa, cliente e moeda</label><select id="credit-apply-invoice" class="form-control" name="movement[invoice_id]" required><option value="">Selecione</option><?php foreach($invoices as $invoice){?><option value="<?= (int)$invoice['id']; ?>"><?= $esc($invoice['formatted_number'].' · total '.$invoice['total']); ?></option><?php } ?></select><?php $movementField='apply';require APPPATH.'views/admin/credit_notes/movement_fields.php'; ?><button type="submit">Aplicar crédito local</button><?= form_close(); ?><?php } ?>
<h3>Registrar reembolso comprovado</h3><?= form_open($url());$hidden('refund'); ?><input type="hidden" name="credit_id" value="<?= $id; ?>"><p>Informe a evidência de um reembolso já realizado. Esta ação apenas registra o fato no CRM; não solicita devolução ao banco ou ao Asaas.</p><?php $movementField='refund';require APPPATH.'views/admin/credit_notes/movement_fields.php'; ?><button type="submit">Registrar reembolso manual comprovado</button><?= form_close(); ?><?php } ?>
<?php if($document['status']!==3&&!$document['entries']&&$capabilities['delete']){?><?= form_open($url());$hidden('void'); ?><input type="hidden" name="credit_id" value="<?= $id; ?>"><p>Cancelar conserva o documento e o número. Notas com histórico de movimento não são canceláveis.</p><button type="submit">Cancelar nota sem movimento</button><?= form_close(); ?><?php } ?><p><a href="<?= $esc($url()); ?>">Voltar à lista</a></p><?php } ?>
<h2>Notas da empresa</h2><table class="table"><thead><tr><th>Número</th><th>Emissão</th><th>Total</th><th>Estado</th></tr></thead><tbody><?php foreach($directory['items'] as $row){?><tr><td><a href="<?= $esc($url('?credit='.(int)$row['id'])); ?>"><?= $esc($row['formatted_number']); ?></a></td><td><?= $esc($row['date']); ?></td><td><?= $esc($row['currency'].' '.$row['total']); ?></td><td><?= $esc($states[(int)$row['status']]??'Revisão'); ?></td></tr><?php } ?></tbody></table><?php if($directory['next']!==null){?><a href="<?= $esc($url('?after='.$directory['next'])); ?>">Próxima página</a><?php } ?>
<?php if($capabilities['create']){?><h2>Emitir nota de crédito</h2><?= form_open($url());$hidden('create'); ?><label for="credit-client">Cliente autorizado</label><select id="credit-client" class="form-control" name="credit[client_id]" required><option value="">Selecione</option><?php foreach($clients as $client){?><option value="<?= (int)$client['userid']; ?>"><?= $esc($client['company']); ?></option><?php } ?></select><label for="credit-currency">Moeda</label><select id="credit-currency" class="form-control" name="credit[currency]" required><?php foreach($currencies as $currency){?><option value="<?= (int)$currency['id']; ?>"><?= $esc($currency['name']); ?></option><?php } ?></select><label for="credit-date">Emissão</label><input id="credit-date" class="form-control" name="credit[date]" type="date" value="<?= date('Y-m-d'); ?>" required>
<div id="credit-items"><fieldset class="credit-item" data-index="0"><legend>Item 1</legend><label>Descrição<input id="credit-item-description" class="form-control" name="credit[items][0][description]" maxlength="10000" required></label><label>Quantidade<input class="form-control" name="credit[items][0][qty]" value="1.00" inputmode="decimal" required></label><label>Preço unitário<input id="credit-item-rate" class="form-control" name="credit[items][0][rate]" inputmode="decimal" required></label><div class="credit-taxes"><label>Tributo<input class="form-control" name="credit[items][0][taxes][0][name]" maxlength="100"></label><label>Alíquota (%)<input class="form-control" name="credit[items][0][taxes][0][rate]" value="0.00" inputmode="decimal" required></label><button type="button" data-credit-tax-remove="0">Remover tributo</button></div><button type="button" data-credit-tax>Adicionar tributo</button><button type="button" data-credit-remove>Remover item</button></fieldset></div><button type="button" id="credit-add-item">Adicionar item</button>
<label for="credit-discount-mode">Modo de desconto</label><select id="credit-discount-mode" class="form-control" name="credit[discount_mode]"><option value="fixed">Valor fixo</option><option value="percent">Percentual do subtotal</option></select><label for="credit-discount">Desconto</label><input id="credit-discount" class="form-control" name="credit[discount_value]" value="0.00" inputmode="decimal" required><label for="credit-discount-type">Aplicar desconto</label><select id="credit-discount-type" class="form-control" name="credit[discount_type]"><option value="after_tax">Após tributos</option><option value="before_tax">Antes dos tributos</option></select><label for="credit-adjustment">Ajuste (permite negativo)</label><input id="credit-adjustment" class="form-control" name="credit[adjustment]" value="0.00" inputmode="decimal" required><label for="credit-note">Observação</label><textarea id="credit-note" class="form-control" name="credit[note]" maxlength="20000"></textarea><button type="submit">Emitir nota de crédito da empresa</button><?= form_close(); ?><?php } ?>
<p>Operações bancárias vinculadas continuam exigindo a integração de origem. Não há transmissão de reembolso nesta tela.</p></section>
<script>
(function(){'use strict';var host=document.getElementById('credit-items'),add=document.getElementById('credit-add-item');if(!host||!add)return;var next=1;
function buttons(){host.querySelectorAll('[data-credit-remove]').forEach(function(button){button.disabled=host.children.length===1;button.title=button.disabled?'Mantenha ao menos um item':'';});add.disabled=host.children.length>=100;}
add.addEventListener('click',function(){if(host.children.length>=100)return;var node=host.firstElementChild.cloneNode(true),index=next++;node.dataset.index=String(index);node.querySelector('legend').textContent='Item '+(index+1);node.querySelectorAll('[id]').forEach(function(el){el.removeAttribute('id');});node.querySelectorAll('input').forEach(function(el){el.name=el.name.replace(/credit\[items\]\[\d+\]/,'credit[items]['+index+']');el.value=el.name.endsWith('[qty]')?'1.00':el.name.endsWith('[rate]')&&el.name.includes('[taxes]')?'0.00':'';});var taxes=node.querySelector('.credit-taxes');while(taxes.firstChild)taxes.removeChild(taxes.firstChild);node.querySelector('[data-credit-tax]').disabled=false;host.appendChild(node);buttons();});
host.addEventListener('click',function(event){if(event.target.hasAttribute('data-credit-remove')){if(host.children.length>1)event.target.closest('fieldset').remove();buttons();return;}
if(event.target.hasAttribute('data-credit-tax-remove')){var target=event.target.closest('fieldset'),taxes=target.querySelector('.credit-taxes'),taxIndex=event.target.getAttribute('data-credit-tax-remove');taxes.querySelectorAll('input').forEach(function(input){if(input.name.includes('[taxes]['+taxIndex+']'))input.closest('label').remove();});event.target.remove();target.querySelector('[data-credit-tax]').disabled=false;return;}
if(!event.target.hasAttribute('data-credit-tax'))return;var field=event.target.closest('fieldset'),taxes=field.querySelector('.credit-taxes'),inputs=taxes.querySelectorAll('input');if(inputs.length>=20)return;var index=0;inputs.forEach(function(input){var matched=input.name.match(/\[taxes\]\[(\d+)\]/);if(matched)index=Math.max(index,Number(matched[1])+1);});['name','rate'].forEach(function(key){var label=document.createElement('label');label.textContent=key==='name'?'Tributo':'Alíquota (%)';var input=document.createElement('input');input.className='form-control';input.name='credit[items]['+field.dataset.index+'][taxes]['+index+']['+key+']';if(key==='name')input.maxLength=100;else{input.value='0.00';input.inputMode='decimal';input.required=true;}label.appendChild(input);taxes.appendChild(label);});var remove=document.createElement('button');remove.type='button';remove.setAttribute('data-credit-tax-remove',String(index));remove.textContent='Remover tributo';taxes.appendChild(remove);event.target.disabled=taxes.querySelectorAll('input').length>=20;});buttons();})();
</script>
